// Package: Microsoft.SemanticKernel
// End-to-end RAG pipeline using Semantic Kernel memory and chat completion.

using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Memory;
using Microsoft.SemanticKernel.Text;

public sealed class SemanticKernelRagPipeline
{
    private readonly Kernel _kernel;
    private readonly ISemanticTextMemory _memory;
    private const string CollectionName = "rag-documents";

    public SemanticKernelRagPipeline(Kernel kernel, ISemanticTextMemory memory)
    {
        _kernel = kernel ?? throw new ArgumentNullException(nameof(kernel));
        _memory = memory ?? throw new ArgumentNullException(nameof(memory));
    }

    public async Task IngestAsync(
        IEnumerable<string> documents,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(documents);

        var chunker = new TextChunker();
        var chunkIndex = 0;

        foreach (var document in documents)
        {
            var chunks = chunker.SplitPlainTextLines(document, maxTokensPerChunk: 128);

            foreach (var chunk in chunks)
            {
                await _memory.SaveInformationAsync(
                    collection: CollectionName,
                    text: chunk,
                    id: $"chunk-{chunkIndex}",
                    description: "Document chunk",
                    cancellationToken: ct);

                chunkIndex++;
            }
        }
    }

    public async Task<string> AskAsync(string question, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(question);

        var memories = await _memory.SearchAsync(
            collection: CollectionName,
            query: question,
            limit: 5,
            withEmbeddings: false,
            cancellationToken: ct);

        var context = string.Join(
            "\n---\n",
            memories.Select(m => m.Metadata.Text));

        var prompt = $"""
Context:
{context}

Question:
{question}

Answer using only the context above. If the answer is not in the context, say so.
""";

        var settings = new PromptExecutionSettings
        {
            Temperature = 0.3,
            MaxTokens = 500
        };

        var result = await _kernel.InvokePromptAsync<string>(
            prompt,
            new(settings),
            ct);

        return result;
    }
}

